$worker$;CREATE TEMP TABLE receipt77693_inner(v jsonb);EXECUTE $testsql$DO $tests$ DECLARE taskrec record;aid uuid;tok text:='receipt77693-rollback-fixture';v jsonb;v2sha text;got text;negs int:=0;it record;n int;rid text:='practical-delivery-v1-76076';BEGIN
v2sha:=encode(sha256(convert_to(pg_get_functiondef('population_top3000_202608_202609_v1.practical_delivery_worker_v2(uuid,text)'::regprocedure),'UTF8')),'hex');
UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_oid='population_top3000_202608_202609_v1.practical_delivery_worker_v2(uuid,text)'::regprocedure,function_sha256=v2sha WHERE family_id='REF03' AND stage='DELIVER';
FOR taskrec IN SELECT * FROM population_top3000_202608_202609_v1.pipeline_task WHERE payload->>'release_id'=rid AND (payload->>'kind'='PRACTICAL_DELIVERY_VERIFY_V1' OR payload->>'kind'='PRACTICAL_DELIVERY_EXPORT_V1' AND payload->>'dataset'='companies') ORDER BY payload->>'kind',payload->>'target_family' LOOP
 aid:=gen_random_uuid();INSERT INTO population_top3000_202608_202609_v1.pipeline_attempt(attempt_id,task_id,execution_number,token_sha256,owner_fence,stop_generation,adapter_sha256,outcome)VALUES(aid,taskrec.task_id,taskrec.executions+1,encode(sha256(convert_to(tok,'UTF8')),'hex'),3,1,v2sha,'RUNNING');UPDATE population_top3000_202608_202609_v1.pipeline_task SET status='LEASED',attempt_id=aid,executions=executions+1,owner_fence=3,stop_generation=1,lease_until=clock_timestamp()+interval '3minutes' WHERE task_id=taskrec.task_id;
 v:=population_top3000_202608_202609_v1.practical_delivery_worker_v2(aid,tok);got:=v#>>'{commit_receipt,immutable_output_ids,0}';
 IF got IS DISTINCT FROM rid||':'||coalesce(taskrec.payload->>'target_family',taskrec.payload->>'dataset')||':'||coalesce(taskrec.payload->>'partition','coverage') OR v->>'state' IS DISTINCT FROM 'COMPLETE' OR (v#>>'{commit_receipt,new_committed_units}')::int<>0 THEN RAISE EXCEPTION 'RECEIPT77693_D02_S02_EXPORT_REPLAY';END IF;
 IF population_top3000_202608_202609_v1.practical_delivery_worker_v2(aid,tok) IS DISTINCT FROM v THEN RAISE EXCEPTION 'RECEIPT77693_REPLAY_CHANGED';END IF;
 FOR it IN SELECT * FROM(VALUES
 ('stop',$m$UPDATE population_top3000_202608_202609_v1.acquisition_control SET stopped=true WHERE singleton$m$,'MISSION_HELD_OR_ADMISSION_EXPIRED'),
 ('staleowner',$m$UPDATE population_top3000_202608_202609_v1.acquisition_control SET owner_fence=4 WHERE singleton$m$,'CONTROLLER_OWNERSHIP_CHANGED'),
 ('scope',$m$UPDATE population_top3000_202608_202609_v1.acquisition_control SET scope_sha256=repeat('0',64) WHERE singleton$m$,'SCOPE_MISMATCH'),
 ('admission',$m$UPDATE population_top3000_202608_202609_v1.acquisition_control SET admitted_until=clock_timestamp()-interval '1second' WHERE singleton$m$,'MISSION_HELD_OR_ADMISSION_EXPIRED'),
 ('code',$m$UPDATE population_top3000_202608_202609_v1.pipeline_adapter SET function_sha256=repeat('0',64) WHERE family_id='REF03'AND stage='DELIVER'$m$,'ADAPTER_CODE_CHANGED'),
 ('source',$m$UPDATE population_top3000_202608_202609_v1.daily_shared_run_v1 SET input_versions=input_versions||'{"test_changed":true}' WHERE run_id='19a35bfa-6023-4092-9809-3ed950871d7f'$m$,'PRACTICAL_DELIVERY_DAILY_INPUT_PIN'))x(name,mutation,want) LOOP
 BEGIN EXECUTE it.mutation;PERFORM population_top3000_202608_202609_v1.practical_delivery_worker_v2(aid,tok);RAISE EXCEPTION 'RECEIPT77693_NEGATIVE_ACCEPTED %',it.name;EXCEPTION WHEN raise_exception THEN IF SQLERRM IS DISTINCT FROM it.want THEN RAISE;END IF;END;negs:=negs+1;END LOOP;
 BEGIN UPDATE population_top3000_202608_202609_v1.pipeline_task SET input_versions=input_versions-'release_manifest_sha256' WHERE task_id=taskrec.task_id;PERFORM population_top3000_202608_202609_v1.practical_delivery_worker_v2(aid,tok);RAISE EXCEPTION 'RECEIPT77693_NULL_VERSION_ACCEPTED';EXCEPTION WHEN raise_exception THEN IF SQLERRM IS DISTINCT FROM 'PRACTICAL_DELIVERY_TASK_INPUT_PIN' THEN RAISE;END IF;END;negs:=negs+1;
 UPDATE population_top3000_202608_202609_v1.pipeline_task SET status=taskrec.status,attempt_id=taskrec.attempt_id,executions=taskrec.executions,owner_fence=taskrec.owner_fence,stop_generation=taskrec.stop_generation,lease_until=taskrec.lease_until WHERE task_id=taskrec.task_id;
 UPDATE population_top3000_202608_202609_v1.pipeline_attempt SET outcome='COMPLETE',ended_at=clock_timestamp() WHERE attempt_id=aid;
END LOOP;
IF negs<>21 THEN RAISE EXCEPTION 'RECEIPT77693_EXPECTED21_NEGATIVES %',negs;END IF;
